"""
Integration tests for visualization generation (T035a, T035b).
"""
import os
import pytest
from pathlib import Path
import json

# Ensure code is importable
import sys
sys.path.insert(0, str(Path(__file__).parent.parent.parent))

from code.config import RESULTS_ROOT

class TestVisualsGeneration:
    """Tests for visual output existence and validity."""

    @pytest.fixture(autouse=True)
    def setup(self):
        """Ensure required files exist before running tests."""
        # Note: In a real CI, these would be generated by running the pipeline.
        # Here we assume the pipeline has run or we are testing the existence logic.
        pass

    def test_regression_plot_exists(self):
        """T035a: Assert that results/figures/regression_plot.png exists and is not empty."""
        path = Path(RESULTS_ROOT) / "figures" / "regression_plot.png"
        
        # If the file doesn't exist, the test fails (as expected if pipeline not run)
        assert path.exists(), f"Regression plot not found at {path}"
        assert path.stat().st_size > 0, "Regression plot file is empty"

    def test_sensitivity_table_exists(self):
        """T035b: Assert that results/figures/sensitivity_table.png exists and is not empty."""
        path = Path(RESULTS_ROOT) / "figures" / "sensitivity_table.png"
        
        assert path.exists(), f"Sensitivity table not found at {path}"
        assert path.stat().st_size > 0, "Sensitivity table file is empty"

    def test_stratified_plot_exists(self):
        """Extra: Assert stratified plot exists."""
        path = Path(RESULTS_ROOT) / "figures" / "stratified_plot.png"
        
        assert path.exists(), f"Stratified plot not found at {path}"
        assert path.stat().st_size > 0, "Stratified plot file is empty"

    def test_final_report_exists(self):
        """Extra: Assert final report exists."""
        path = Path(RESULTS_ROOT) / "final_report.json"
        
        assert path.exists(), f"Final report not found at {path}"
        
        # Validate JSON structure
        with open(path, 'r') as f:
            data = json.load(f)
        
        assert 'status' in data
        assert data['status'] == 'complete'
        assert 'disclaimer' in data